Object.assign(translations.de.grandbaie!, { metadata: { title: "Grand Baie entdecken", description: "Grand Baie auf Mauritius: Strände, Shopping, Nachtleben und Bootsausflüge im lebendigsten Ort des Nordens." }, sections: [[["Grand Baie Beach & Bay", "ruhige türkisfarbene Bucht, Schwimmen und Sonnenuntergänge"], ["La Cuvette Beach", "ruhiger öffentlicher Strand im Ort"], ["Grand Baie Bazaar", "Kunsthandwerk, Textilien und Souvenirs"], ["Bars & restaurants", "das lebendigste Essen- und Nachtleben im Norden"], ["Catamaran cruises", "Bootsfahrten zu den nördlichen Inseln"]], [["Pereybere Beach", "geschützter Badestrand - 5 Min."], ["Cap Malheureux", "Kirche mit rotem Dach und Inselblick - 15 Min."], ["Northern Islands", "Schnorcheln bei Gabriel und Flat Island, per Boot"], ["Mont Choisy Beach", "lange von Kasuarinen gesäumte Bucht - 10 Min."], ["Pamplemousses Garden", "riesige Seerosen und Palmen - 20 Min."]]], whyTitle: "Warum Grand Baie", whyText: "Der soziale Mittelpunkt des Nordens statt einer stillen Zuflucht: Bucht, Boutiquen und Trubel, mit Stränden, Inseln und Gärten in kurzer Fahrdistanz.", mapAlt: "Karte von Mauritius mit Grand Baie an der Nordküste", mapCaption: "Grand Baie: die Nordküste", sideCards: [["Beste Zeit", "Sonnenuntergang - für Bars, Buchtblick und Atmosphäre."], ["Anreise", "Etwa 1 Std. vom Flughafen; etwa 20 Min. von Port Louis."], ["Kombinieren mit", "Cap Malheureux und Pereybere Beach."]], goodItems: [["Bestes Licht", "Goldene Stunde über der Bucht für Fotos und Sundowner."], ["Vorab buchen", "Katamaranfahrten in der Hochsaison reservieren."], ["Bargeld und Karten", "Karten sind verbreitet; Bargeld für den Basar mitnehmen."], ["Lebendige Basis", "Der quirligste Ort des Nordens für Essen und Nachtleben."]] });
Object.assign(translations.de.chamarel!, { metadata: { title: "Chamarel entdecken", description: "Chamarel auf Mauritius: Siebenfarbige Erde, Wasserfall, Rum, Kaffee und einheimischer Wald." }, sections: [[["Chamarel Waterfall", "der höchste einstufige Wasserfall der Insel"], ["Seven Coloured Earth", "berühmte mehrfarbige Vulkandünen"], ["Ebony Forest", "Reservat mit einheimischem Wald und Sublime Point"], ["Chamarel Viewpoint", "weite Berg- und Westküstenblicke"], ["Black River Gorges View", "Waldpanorama und oft Affen"]], [["La Rhumerie de Chamarel", "aktive Rumdestillerie mit Verkostungen"], ["Cafe de Chamarel", "die einzige Kaffeeplantage der Insel"], ["Curious Mauritius", "Illusionsmuseum, gut bei Regen"], ["Giant Tortoises", "Aldabra-Schildkröten bei Seven Earth"], ["L'Alchimiste", "feine kreolische Küche mit Talblick"]]], whyTitle: "Warum Chamarel", whyText: "Das Natur- und Geschmackszentrum der Insel: keine Strände, dafür Wasserfälle, farbige Erde, Wald, Rum, Kaffee und kühle Bergluft.", mapAlt: "Karte von Mauritius mit Chamarel im südwestlichen Hochland", mapCaption: "Chamarel: das südwestliche Hochland", sideCards: [["Beste Zeit", "Ein trockener, sonniger Morgen - beste Farben und weniger Menschen."], ["Anreise", "20-30 Min. von Le Morne; etwa 1,25 Std. vom Flughafen."], ["Dauer", "2-3 Std. für die Hauptorte; ein halber Tag mit Rum oder Wald."]], goodItems: [["Früh starten", "Kühleres Licht, klarere Farben und ruhigere Wege."], ["Ein Ticket", "Chamarel Falls und Seven Coloured Earth teilen sich den Eingang."], ["Passend kleiden", "Feste Schuhe und leichte Jacke fürs Hochland."], ["Vorab buchen", "Gute Restaurants in der Hochsaison reservieren."]] });
Object.assign(translations.de.mahebourg!, { metadata: { title: "Mahébourg entdecken", description: "Mahébourg auf Mauritius: historisches Dorf, Waterfront, Montagsmarkt, Marinemuseum und Blue Bay." }, sections: [[["Mahebourg Waterfront", "ruhige Lagunenblicke und lokales Leben"], ["Monday Market", "Streetfood, Shopping und Trubel"], ["National History Museum", "koloniales Herrenhaus und Marinegeschichte"], ["Notre Dame des Anges", "die markante Dorfkirche"], ["Local eateries", "authentische mauritische Hausmannskost"]], [["Blue Bay Marine Park", "Schnorcheln und Glasbodenboote - 10 Min."], ["Ile aux Aigrettes", "Naturschutzinsel per Boot"], ["Pointe d'Esny", "ruhiger türkisfarbener Lagunenstrand - 5-10 Min."], ["La Vallee de Ferney", "Wandern im einheimischen Wald - 20-30 Min."], ["Lion Mountain", "Gratwanderung im Südosten - 15-25 Min."]]], whyTitle: "Warum Mahébourg", whyText: "Ein echtes Arbeitsdorf statt Resortstreifen: Montagsmarkt, Marinegeschichte und eine einfache Basis für Blue Bay, Inseln und südliche Waldwege.", mapAlt: "Karte von Mauritius mit Mahébourg an der Südostküste", mapCaption: "Mahébourg: die Südostküste", sideCards: [["Bester Tag", "Montag - für den großen Wochenmarkt."], ["Anreise", "Etwa 45 Min. vom Flughafen; etwa 1 Std. vom Westen."], ["Kombinieren mit", "Blue Bay und Pointe d'Esny."]], goodItems: [["Bestes Licht", "Die Waterfront morgens oder am späten Nachmittag besuchen."], ["Markttag", "Bargeld zum Montagsmarkt mitbringen und früh gehen."], ["Vorab buchen", "Touren nach Ile aux Aigrettes reservieren."], ["Langsam und echt", "Eine authentische, unpolierte Basis im Südosten."]] });
