Object.assign(translations.it.grandbaie!, { metadata: { title: "Esplorando Grand Baie", description: "Grand Baie a Mauritius: spiagge, shopping, vita notturna e gite in barca nel nord più vivace." }, sections: [[["Grand Baie Beach & Bay", "baia turchese calma, nuoto e tramonti"], ["La Cuvette Beach", "spiaggia pubblica più tranquilla in città"], ["Grand Baie Bazaar", "artigianato, tessuti e souvenir"], ["Bars & restaurants", "la zona più vivace del nord per cena e nightlife"], ["Catamaran cruises", "gite in barca verso le isole del nord"]], [["Pereybere Beach", "spiaggia riparata per nuotare - 5 min"], ["Cap Malheureux", "chiesa dal tetto rosso e vista sugli isolotti - 15 min"], ["Northern Islands", "snorkeling a Gabriel e Flat Island, in barca"], ["Mont Choisy Beach", "lunga baia bordata di casuarine - 10 min"], ["Pamplemousses Garden", "ninfee giganti e palme - 20 min"]]], whyTitle: "Perché Grand Baie", whyText: "Il centro sociale del nord più che un rifugio silenzioso: baia, boutique e movimento, con spiagge, isole e giardini a breve distanza.", mapAlt: "Mappa di Mauritius con Grand Baie sulla costa nord", mapCaption: "Grand Baie: la costa nord", sideCards: [["Momento migliore", "Tramonto, per bar, vista baia e atmosfera."], ["Come arrivare", "Circa 1 h dall'aeroporto; circa 20 min da Port Louis."], ["Abbinala a", "Cap Malheureux e Pereybere Beach."]], goodItems: [["Luce migliore", "Ora dorata sulla baia per foto e aperitivi."], ["Prenota", "Riserva le gite in catamarano in alta stagione."], ["Contanti e carte", "Carte spesso accettate; porta contanti per il bazar."], ["Base vivace", "Il posto più animato del nord per cena e nightlife."]] });
Object.assign(translations.it.chamarel!, { metadata: { title: "Esplorando Chamarel", description: "Chamarel a Mauritius: Terre dei Sette Colori, cascata, rum, caffè e foresta nativa." }, sections: [[["Chamarel Waterfall", "la cascata a salto unico più alta dell'isola"], ["Seven Coloured Earth", "famose dune vulcaniche multicolori"], ["Ebony Forest", "riserva di foresta nativa e Sublime Point"], ["Chamarel Viewpoint", "ampie viste su montagne e costa ovest"], ["Black River Gorges View", "panorama forestale e possibili scimmie"]], [["La Rhumerie de Chamarel", "distilleria di rum attiva e degustazioni"], ["Cafe de Chamarel", "l'unica piantagione di caffè dell'isola"], ["Curious Mauritius", "museo delle illusioni, utile con la pioggia"], ["Giant Tortoises", "tartarughe di Aldabra a Seven Earth"], ["L'Alchimiste", "cucina creola raffinata con vista valle"]]], whyTitle: "Perché Chamarel", whyText: "Il cuore natura e sapori dell'isola: niente spiagge, ma cascate, terre colorate, foresta nativa, rum, caffè e aria fresca di montagna.", mapAlt: "Mappa di Mauritius con Chamarel negli altopiani sud-occidentali", mapCaption: "Chamarel: gli altopiani del sud-ovest", sideCards: [["Momento migliore", "Mattina asciutta e soleggiata: colori migliori, meno folla."], ["Come arrivare", "20-30 min da Le Morne; circa 1,25 h dall'aeroporto."], ["Durata", "2-3 h per i luoghi; mezza giornata con rum o foresta."]], goodItems: [["Vai presto", "Luce più fresca, colori più netti e sentieri più tranquilli."], ["Un biglietto", "Chamarel Falls e Seven Coloured Earth condividono l'ingresso."], ["Vestiti bene", "Scarpe robuste e giacca leggera per gli altopiani."], ["Prenota", "Riserva i buoni ristoranti in alta stagione."]] });
Object.assign(translations.it.mahebourg!, { metadata: { title: "Esplorando Mahébourg", description: "Mahébourg a Mauritius: villaggio storico, waterfront, mercato del lunedì, museo navale e Blue Bay." }, sections: [[["Mahebourg Waterfront", "vista calma sulla laguna e vita locale"], ["Monday Market", "street food, shopping e fermento"], ["National History Museum", "dimora coloniale e passato navale"], ["Notre Dame des Anges", "la chiesa simbolo del villaggio"], ["Local eateries", "autentica cucina casalinga mauriziana"]], [["Blue Bay Marine Park", "snorkeling e barche con fondo di vetro - 10 min"], ["Ile aux Aigrettes", "isola di conservazione, in barca"], ["Pointe d'Esny", "spiaggia tranquilla in laguna turchese - 5-10 min"], ["La Vallee de Ferney", "trekking nella foresta nativa - 20-30 min"], ["Lion Mountain", "escursione di cresta nel sud-est - 15-25 min"]]], whyTitle: "Perché Mahébourg", whyText: "Un vero villaggio vivo più che una striscia di resort: mercato del lunedì, storia navale e base facile per Blue Bay, isole e foreste del sud.", mapAlt: "Mappa di Mauritius con Mahébourg sulla costa sud-est", mapCaption: "Mahébourg: la costa sud-est", sideCards: [["Giorno migliore", "Lunedì, per il grande mercato settimanale."], ["Come arrivare", "Circa 45 min dall'aeroporto; circa 1 h dall'ovest."], ["Abbinala a", "Blue Bay e Pointe d'Esny."]], goodItems: [["Luce migliore", "Vedi il waterfront al mattino o nel tardo pomeriggio."], ["Giorno di mercato", "Porta contanti al mercato del lunedì e vai presto."], ["Prenota", "Riserva i tour di conservazione a Ile aux Aigrettes."], ["Lento e vero", "Una base sud-est autentica e non patinata."]] });
