Object.assign(translations.es.grandbaie!, { metadata: { title: "Explorando Grand Baie", description: "Grand Baie en Mauricio: playas, compras, vida nocturna y barcos en el norte más animado." }, sections: [[["Grand Baie Beach & Bay", "bahía turquesa tranquila, baño y puestas de sol"], ["La Cuvette Beach", "playa pública más tranquila dentro del pueblo"], ["Grand Baie Bazaar", "artesanía, textiles y recuerdos"], ["Bars & restaurants", "la zona más viva del norte para cenar y salir"], ["Catamaran cruises", "barcos hacia las islas del norte"]], [["Pereybere Beach", "playa protegida para nadar - 5 min"], ["Cap Malheureux", "iglesia de techo rojo y vistas a islotes - 15 min"], ["Northern Islands", "snorkel en Gabriel y Flat Island, en barco"], ["Mont Choisy Beach", "larga bahía con casuarinas - 10 min"], ["Pamplemousses Garden", "nenúfares gigantes y palmeras - 20 min"]]], whyTitle: "Por qué Grand Baie", whyText: "El centro social del norte más que un retiro tranquilo: bahía, boutiques y ambiente, con playas, islas y jardines a poca distancia.", mapAlt: "Mapa de Mauricio con Grand Baie en la costa norte", mapCaption: "Grand Baie: la costa norte", sideCards: [["Mejor momento", "Atardecer, para bares, vistas de la bahía y ambiente."], ["Cómo llegar", "Aprox. 1 h desde el aeropuerto; aprox. 20 min desde Port Louis."], ["Combínalo con", "Cap Malheureux y Pereybere Beach."]], goodItems: [["Mejor luz", "Hora dorada sobre la bahía para fotos y copas."], ["Reserva", "Reserva catamaranes en temporada alta."], ["Efectivo y tarjetas", "Tarjetas bastante aceptadas; lleva efectivo para el bazar."], ["Base animada", "El lugar más vivo del norte para cenar y salir."]] });
Object.assign(translations.es.chamarel!, { metadata: { title: "Explorando Chamarel", description: "Chamarel en Mauricio: Tierra de Siete Colores, cascada, ron, café y bosque nativo." }, sections: [[["Chamarel Waterfall", "la cascada de caída única más alta de la isla"], ["Seven Coloured Earth", "famosas dunas volcánicas multicolor"], ["Ebony Forest", "reserva de bosque nativo y Sublime Point"], ["Chamarel Viewpoint", "vistas amplias de montaña y costa oeste"], ["Black River Gorges View", "panorama de bosque y posibles monos"]], [["La Rhumerie de Chamarel", "destilería de ron activa y degustaciones"], ["Cafe de Chamarel", "la única plantación de café de la isla"], ["Curious Mauritius", "museo de ilusiones, ideal con lluvia"], ["Giant Tortoises", "tortugas de Aldabra en Seven Earth"], ["L'Alchimiste", "cocina criolla refinada con vistas al valle"]]], whyTitle: "Por qué Chamarel", whyText: "El corazón natural y de sabores de la isla: sin playas, pero con cascadas, tierra de colores, bosque nativo, ron, café y aire fresco de montaña.", mapAlt: "Mapa de Mauricio con Chamarel en las tierras altas del suroeste", mapCaption: "Chamarel: las tierras altas del suroeste", sideCards: [["Mejor momento", "Mañana seca y soleada: mejores colores y menos gente."], ["Cómo llegar", "20-30 min desde Le Morne; aprox. 1,25 h desde el aeropuerto."], ["Duración", "2-3 h para los sitios; medio día con ron o bosque."]], goodItems: [["Ve temprano", "Luz más fresca, colores más claros y senderos más tranquilos."], ["Una entrada", "Chamarel Falls y Seven Coloured Earth comparten acceso."], ["Vístete bien", "Zapatos firmes y chaqueta ligera para las tierras altas."], ["Reserva", "Reserva buenos restaurantes en temporada alta."]] });
Object.assign(translations.es.mahebourg!, { metadata: { title: "Explorando Mahébourg", description: "Mahébourg en Mauricio: pueblo histórico, waterfront, mercado del lunes, museo naval y Blue Bay." }, sections: [[["Mahebourg Waterfront", "vistas tranquilas de la laguna y vida local"], ["Monday Market", "comida callejera, compras y ambiente"], ["National History Museum", "mansión colonial y pasado naval"], ["Notre Dame des Anges", "la iglesia emblemática del pueblo"], ["Local eateries", "auténtica cocina casera mauriciana"]], [["Blue Bay Marine Park", "snorkel y barcos de fondo de cristal - 10 min"], ["Ile aux Aigrettes", "isla de conservación, en barco"], ["Pointe d'Esny", "playa tranquila de laguna turquesa - 5-10 min"], ["La Vallee de Ferney", "senderismo en bosque nativo - 20-30 min"], ["Lion Mountain", "ruta de cresta en el sureste - 15-25 min"]]], whyTitle: "Por qué Mahébourg", whyText: "Un pueblo real y activo, no una franja de resorts: mercado del lunes, historia naval y base fácil para Blue Bay, las islas y los bosques del sur.", mapAlt: "Mapa de Mauricio con Mahébourg en la costa sureste", mapCaption: "Mahébourg: la costa sureste", sideCards: [["Mejor día", "Lunes, por el gran mercado semanal."], ["Cómo llegar", "Aprox. 45 min desde el aeropuerto; aprox. 1 h desde el oeste."], ["Combínalo con", "Blue Bay y Pointe d'Esny."]], goodItems: [["Mejor luz", "Ve el waterfront por la mañana o al final de la tarde."], ["Día de mercado", "Lleva efectivo al mercado del lunes y ve temprano."], ["Reserva", "Reserva los tours de conservación a Ile aux Aigrettes."], ["Lento y real", "Una base del sureste auténtica y sin pulir."]] });
Object.assign(translations.es.morneChamarel!, { metadata: { title: "Le Morne y Chamarel", description: "Le Morne y Chamarel en Mauricio: montaña UNESCO, laguna, cascadas, Tierra de Siete Colores y costa salvaje." }, sections: [[["Le Morne Brabant", "senderismo hasta la cumbre UNESCO"], ["Le Morne Beach", "laguna, atardeceres y kitesurf"], ["Lagoon Snorkelling", "agua clara protegida por el arrecife"]], [["Chamarel Waterfall", "cascada de bosque de unos 100 m"], ["Seven Coloured Earth", "dunas volcánicas arcoíris"], ["Ebony Forest", "bosque nativo y conservación"], ["Chamarel Village", "currys criollos y ron de finca"]], [["Black River Gorges View", "amplias vistas de las tierras altas"], ["Piton P. Riviere Noire", "la cima más alta de la isla"], ["Maconde", "mirador costero dramático"]]], mapAlt: "Mapa de Mauricio con Le Morne y Chamarel en el suroeste", mapCaption: "Le Morne · Chamarel", sideCards: [["Ideal para", "Senderismo, fotografía y viaje lento y escénico."], ["Elige bien la hora", "Empieza temprano y termina en la costa al atardecer."]], goodItems: [["Ve despacio", "El suroeste es más verde y tranquilo: no lo apresures."], ["Una entrada", "Chamarel Falls y Seven Coloured Earth comparten acceso."], ["Camina con cuidado", "Sube Le Morne con guía y respeta su historia."], ["Hora dorada", "Empieza temprano y termina junto al mar con la mejor luz."]] });

Object.assign(translations.ru.grandbaie!, { metadata: { title: "Исследуем Grand Baie", description: "Grand Baie на Маврикии: пляжи, шопинг, ночная жизнь и лодочные прогулки на оживленном севере." }, sections: [[["Grand Baie Beach & Bay", "спокойная бирюзовая бухта, купание и закаты"], ["La Cuvette Beach", "более тихий общественный пляж в городе"], ["Grand Baie Bazaar", "ремесла, текстиль и сувениры"], ["Bars & restaurants", "самая живая зона севера для ужинов и ночной жизни"], ["Catamaran cruises", "лодочные поездки к северным островам"]], [["Pereybere Beach", "защищенный пляж для купания - 5 мин"], ["Cap Malheureux", "церковь с красной крышей и виды на островки - 15 мин"], ["Northern Islands", "сноркелинг у Gabriel и Flat Island, на лодке"], ["Mont Choisy Beach", "длинная бухта с казуаринами - 10 мин"], ["Pamplemousses Garden", "гигантские кувшинки и пальмы - 20 мин"]]], whyTitle: "Почему Grand Baie", whyText: "Социальный центр севера, а не тихое убежище: бухта, бутики и энергия, а пляжи, острова и сады совсем рядом.", mapAlt: "Карта Маврикия с Grand Baie на северном побережье", mapCaption: "Grand Baie: северное побережье", sideCards: [["Лучшее время", "Закат - для баров, видов на бухту и атмосферы."], ["Как добраться", "Около 1 ч от аэропорта; около 20 мин от Port Louis."], ["Совместить с", "Пляжи Cap Malheureux и Pereybere."]], goodItems: [["Лучший свет", "Золотой час над бухтой для фото и напитков."], ["Бронируйте заранее", "Катамараны в высокий сезон лучше резервировать."], ["Наличные и карты", "Карты часто принимают; наличные нужны для базара."], ["Живая база", "Самое оживленное место севера для ужина и ночной жизни."]] });
Object.assign(translations.ru.chamarel!, { metadata: { title: "Исследуем Chamarel", description: "Chamarel на Маврикии: Семицветная земля, водопад, ром, кофе и родной лес." }, sections: [[["Chamarel Waterfall", "самый высокий одиночный водопад острова"], ["Seven Coloured Earth", "знаменитые многоцветные вулканические дюны"], ["Ebony Forest", "заповедник родного леса и Sublime Point"], ["Chamarel Viewpoint", "широкие виды на горы и западное побережье"], ["Black River Gorges View", "лесная панорама и возможные обезьяны"]], [["La Rhumerie de Chamarel", "действующая ромовая дистиллерия и дегустации"], ["Cafe de Chamarel", "единственная кофейная плантация острова"], ["Curious Mauritius", "музей иллюзий, хорош в дождь"], ["Giant Tortoises", "черепахи Альдабра у Seven Earth"], ["L'Alchimiste", "изысканная креольская кухня с видом на долину"]]], whyTitle: "Почему Chamarel", whyText: "Сердце природы и вкуса острова: без пляжей, зато с водопадами, цветной землей, родным лесом, ромом, кофе и прохладным горным воздухом.", mapAlt: "Карта Маврикия с Chamarel в юго-западном высокогорье", mapCaption: "Chamarel: юго-западное высокогорье", sideCards: [["Лучшее время", "Сухое солнечное утро: ярче цвета и меньше людей."], ["Как добраться", "20-30 мин от Le Morne; около 1 ч 15 мин от аэропорта."], ["Сколько времени", "2-3 ч на основные места; полдня с ромом или лесом."]], goodItems: [["Езжайте рано", "Прохладный свет, яснее цвета и спокойнее тропы."], ["Один билет", "Chamarel Falls и Seven Coloured Earth имеют общий вход."], ["Оденьтесь удобно", "Прочная обувь и легкая куртка для высокогорья."], ["Бронируйте", "Хорошие рестораны в сезон лучше резервировать."]] });
Object.assign(translations.ru.mahebourg!, { metadata: { title: "Исследуем Mahébourg", description: "Mahébourg на Маврикии: историческая деревня, набережная, рынок по понедельникам, морской музей и Blue Bay." }, sections: [[["Mahebourg Waterfront", "спокойные виды на лагуну и местная жизнь"], ["Monday Market", "стритфуд, покупки и оживление"], ["National History Museum", "колониальный особняк и морское прошлое"], ["Notre Dame des Anges", "главная церковь деревни"], ["Local eateries", "настоящая домашняя маврикийская кухня"]], [["Blue Bay Marine Park", "сноркелинг и лодки со стеклянным дном - 10 мин"], ["Ile aux Aigrettes", "остров-заповедник, на лодке"], ["Pointe d'Esny", "тихий пляж бирюзовой лагуны - 5-10 мин"], ["La Vallee de Ferney", "походы по родному лесу - 20-30 мин"], ["Lion Mountain", "маршрут по гребню на юго-востоке - 15-25 мин"]]], whyTitle: "Почему Mahébourg", whyText: "Настоящая рабочая деревня, а не курортная полоса: рынок по понедельникам, морская история и удобная база для Blue Bay, островов и южных лесов.", mapAlt: "Карта Маврикия с Mahébourg на юго-восточном побережье", mapCaption: "Mahébourg: юго-восточное побережье", sideCards: [["Лучший день", "Понедельник - большой еженедельный рынок."], ["Как добраться", "Около 45 мин от аэропорта; около 1 ч с запада."], ["Совместить с", "Blue Bay и Pointe d'Esny."]], goodItems: [["Лучший свет", "Набережную лучше смотреть утром или ближе к вечеру."], ["Рыночный день", "Берите наличные на рынок понедельника и приходите рано."], ["Бронируйте", "Резервируйте туры на Ile aux Aigrettes."], ["Медленно и по-настоящему", "Аутентичная, неприлизанная база юго-востока."]] });
Object.assign(translations.ru.morneChamarel!, { metadata: { title: "Le Morne и Chamarel", description: "Le Morne и Chamarel на Маврикии: гора ЮНЕСКО, лагуна, водопады, Семицветная земля и дикое побережье." }, sections: [[["Le Morne Brabant", "поход на вершину ЮНЕСКО"], ["Le Morne Beach", "лагуна, закаты и кайтсерфинг"], ["Lagoon Snorkelling", "чистая вода, защищенная рифом"]], [["Chamarel Waterfall", "лесной водопад около 100 м"], ["Seven Coloured Earth", "радужные вулканические дюны"], ["Ebony Forest", "родной лес и охрана природы"], ["Chamarel Village", "креольские карри и ром с плантации"]], [["Black River Gorges View", "широкие виды высокогорья"], ["Piton P. Riviere Noire", "самая высокая вершина острова"], ["Maconde", "драматичная смотровая точка у моря"]]], mapAlt: "Карта Маврикия с Le Morne и Chamarel на юго-западе", mapCaption: "Le Morne · Chamarel", sideCards: [["Лучше всего для", "Походов, фотографий и медленного красивого маршрута."], ["Выберите время", "Начните рано и закончите на побережье к закату."]], goodItems: [["Не спешите", "Юго-запад зеленее и спокойнее - не торопитесь."], ["Один билет", "Chamarel Falls и Seven Coloured Earth имеют общий вход."], ["Идите осторожно", "Поднимайтесь на Le Morne с гидом и уважайте его историю."], ["Золотой час", "Начните рано и закончите у моря при лучшем свете."]] });

export function getExploringGuide(locale: string, key: ExploringGuideKey): ExploringGuide {
  const safeLocale = (["en", "fr", "de", "it", "es", "ru"] as const).includes(locale as ExploringLocale) ? (locale as ExploringLocale) : "en";
  return {
    ...englishGuides[key],
    ...translations[safeLocale][key],
  };
}
